<?php
/** Slice 8 — the worker's passes (projection.md "Proof": The worker; §6): forecast_pass once a night after 02:00 site time, suggested_orders on the quarter hour and idempotent per day, a pass's exception caught, one worker.pass row a run. */
require __DIR__ . '/lib.php';
$w = projection_world();
reset_projection();
$marco = person(27);
$a0 = last_activity_id();
$runs = fn () => row_count('forecast_runs');
$wp = fn () => count(activity('worker.pass', $a0));

echo "1. forecast_pass\n";
ri_sql("UPDATE ri_settings SET forecast_method = 'baseline'");
$rep = worker('forecast_pass', ['RI_WORKER_NOW' => site_clock('01:30')]);
ok($rep['errors'] === [] && ($rep['ran']['forecast_pass']['sites'] ?? -1) === 0 && $runs() === 0, 'at 01:30 site time it does nothing');
kernel_state(function ($s) { $s['read'] = ['mode' => 'ok', 'rows' => [['date' => day(1), 'service' => 'Dinner', 'reservations' => 12, 'covers' => 70]]]; return $s; });
if (!one("SELECT 1 FROM day_parts WHERE scope_id = 101 AND service_name = 'Dinner'")) { ri_sql("INSERT INTO day_parts (scope_id, key, name, starts_at, ends_at, service_name) VALUES (101, 'lunch', 'Lunch', '11:00', '15:00', 'Lunch'), (101, 'dinner', 'Dinner', '17:00', '22:00', 'Dinner')"); }
$rep = worker('forecast_pass', ['RI_WORKER_NOW' => site_clock('02:10')]);
ok($rep['errors'] === [] && ($rep['ran']['forecast_pass']['sites'] ?? -1) === 1 && $runs() === 1 && ($rep['ran']['forecast_pass']['items'] ?? 0) === 4, 'at 02:10 it runs once for the site that has sales (the Airport has none): one run of 4 items');
$run = q('SELECT * FROM forecast_runs')[0];
ok($run['method'] === 'baseline' && $run['is_current'] === true && (int) $run['horizon_days'] === 21 && (int) $run['history_days'] === 364 && strtotime($run['made_at']) === strtotime(site_clock('02:10')), 'the run: the setting\'s method, 21 days, 364 of history, stamped with the worker\'s clock');
ok((int) one("SELECT count(*) FROM covers_expected WHERE source = 'reservations'") === 1 && ($rep['ran']['forecast_pass']['covers'] ?? 0) === 1, 'the pass synced the booked covers from Reservations first (K7)');
ok((int) one('SELECT count(*) FROM forecast_accuracy WHERE scope_id = 101') >= 4, 'and scored the baseline');
$rep = worker('forecast_pass', ['RI_WORKER_NOW' => site_clock('02:20')]);
ok(($rep['ran']['forecast_pass']['sites'] ?? -1) === 0 && $runs() === 1, 'not again the same night');
$lg = activity('forecast.run', $a0);
ok(count($lg) === 1 && $lg[0]['source'] === 'cron' && (int) $lg[0]['scope_id'] === 101, 'forecast.run is logged by the worker, source cron');
ri_sql("UPDATE ri_settings SET forecast_method = 'holt_winters'");
ri_sql("INSERT INTO forecast_accuracy (scope_id, menu_item_id, horizon_days, window_days, mae, wape, bias, n) VALUES (101, :i, 7, 28, 0, 0, 0, 28) ON CONFLICT (scope_id, menu_item_id, horizon_days, window_days) DO UPDATE SET wape = 0", ['i' => $w['mi_soda']]);
ri_sql("UPDATE sales_daily SET qty = 60 WHERE scope_id = 101 AND menu_item_id = :i AND business_date BETWEEN current_date - 10 AND current_date - 1 AND day_part_id IS NULL", ['i' => $w['mi_soda']]);
$rep = worker('forecast_pass', ['RI_WORKER_NOW' => site_clock('02:10', 1)]);
$hw = q('SELECT * FROM forecast_runs ORDER BY id DESC LIMIT 1')[0];
ok($rep['errors'] === [] && $runs() === 2 && $hw['method'] === 'holt_winters' && $hw['is_current'] === true && (int) one('SELECT count(*) FROM forecast_runs WHERE is_current') === 1, 'the next night, under the Holt-Winters setting: a second run, the first no longer current');
$pr = q("SELECT * FROM buyer_proposals WHERE kind = 'forecast'");
ok(count($pr) === 1 && (int) $pr[0]['subject_id'] === $w['mi_soda'] && (int) $pr[0]['proposed_by'] === 42 && str_contains($pr[0]['title'], 'got worse') && $pr[0]['status'] === 'proposed', 'an item whose accuracy worsened by more than 0.1 is a `forecast` proposal from the Purchasing agent (the soda, after ten odd days)');
ri_sql("UPDATE sales_daily SET qty = 25 WHERE scope_id = 101 AND menu_item_id = :i AND business_date BETWEEN current_date - 10 AND current_date - 1 AND day_part_id IS NULL", ['i' => $w['mi_soda']]);
$wpBefore = $wp();
$rep = worker('forecast_pass', ['RI_WORKER_NOW' => site_clock('02:10', 2), 'RI_PYTHON' => '/nonexistent/python']);
ok($rep['errors'] !== [] && str_contains($rep['errors'][0], 'forecast_pass') && str_contains($rep['errors'][0], 'forecaster failed') && $runs() === 2 && one('SELECT is_current FROM forecast_runs WHERE id = :i', ['i' => $hw['id']]) === true, 'a pass\'s exception is caught and reported in errors[] — the forecaster failing leaves the current run standing');
ok($wp() === $wpBefore + 1, 'one worker.pass row for that run');

echo "2. suggested_orders\n";
reset_projection();
$due = array_map('intval', array_column(q('SELECT supplier_id FROM ri_suppliers_due(101, 36)'), 'supplier_id'));
$withLines = array_values(array_filter($due, fn ($s) => count(array_filter(suggestion($s), fn ($l) => (float) $l['qty_units'] > 0)) > 0));
$out = shell_exec('RI_WORKER_NOW=' . escapeshellarg(site_clock('06:07')) . ' php -r ' . escapeshellarg('require "' . dirname(__DIR__, 3) . '/app/bootstrap.php"; require "' . dirname(__DIR__, 3) . '/app/features/projection/worker.php"; echo json_encode(projection_pass_suggested(db(), 200, new DateTimeImmutable(getenv("RI_WORKER_NOW")), false));') . ' 2>/dev/null');
ok(str_contains((string) $out, 'not a quarter hour') && row_count('purchase_orders') === (int) one("SELECT count(*) FROM purchase_orders WHERE origin NOT IN ('suggested', 'agent')") + 0 && (int) one("SELECT count(*) FROM purchase_orders WHERE origin = 'agent'") === 0, 'at 06:07 (not a quarter hour) the unforced pass does nothing');
$stockouts = q('SELECT s.*, i.name FROM ri_stockouts_projected(101, 7) s JOIN ingredients i ON i.id = s.ingredient_id ORDER BY s.stockout_on');
$n0 = nid();
$rep = worker('suggested_orders', ['RI_WORKER_NOW' => site_clock('06:15')]);
$rr = $rep['ran']['suggested_orders'] ?? [];
$pos = q("SELECT * FROM purchase_orders WHERE origin = 'agent' ORDER BY id");
ok($rep['errors'] === [] && ($rr['drafted'] ?? -1) === count($withLines) && count($pos) === count($withLines) && count($withLines) >= 1, 'at :15 it drafts a PO (origin agent) for every supplier due with something to order (' . count($withLines) . ')');
ok(count(array_filter($pos, fn ($p) => $p['status'] === 'draft' && (int) $p['created_by'] === 42 && $p['expected_on'] !== null && $p['cutoff_at'] !== null)) === count($pos), 'each a draft by the Purchasing agent with the cut-off and the expected delivery — never sent');
$op = q("SELECT * FROM buyer_proposals WHERE kind = 'order'");
ok(count($op) === count($pos) && (int) $op[0]['drafted_record_id'] === (int) $pos[0]['id'] && $op[0]['drafted_record_type'] === 'purchase_order' && $op[0]['subject_type'] === 'supplier' && (int) $op[0]['proposed_by'] === 42, 'and an `order` proposal beside each, naming the drafted PO');
$sp = q("SELECT * FROM buyer_proposals WHERE kind = 'stockout' ORDER BY subject_id");
ok(count($sp) === count($stockouts) && ($rr['stockouts'] ?? -1) === count($stockouts) && count($stockouts) >= 2 && $sp[0]['subject_type'] === 'ingredient', 'a stock-out proposal for each ingredient projected to run out within a week (' . count($stockouts) . ')');
$soon = array_filter($stockouts, fn ($s) => $s['stockout_on'] <= day(2));
$ns = notes(27, 'stockout', $n0);
ok(count($ns) === count($soon) && count($soon) >= 1, 'the Manager is told of each stock-out within two days (' . count($soon) . ')');
$ad = notes(27, 'agent_drafted', $n0);
ok(count($ad) === count($pos), 'and of each PO the agent drafted');
$rep = worker('suggested_orders', ['RI_WORKER_NOW' => site_clock('06:30')]);
ok(($rep['ran']['suggested_orders']['drafted'] ?? -1) === 0 && ($rep['ran']['suggested_orders']['stockouts'] ?? -1) === 0 && (int) one("SELECT count(*) FROM purchase_orders WHERE origin = 'agent'") === count($pos) && (int) one("SELECT count(*) FROM buyer_proposals") === count($op) + count($sp) && count(notes(27, 'stockout', $n0)) === count($soon), 'at :30 it drafts nothing more, proposes nothing twice and notifies nothing twice');
$out = shell_exec('RI_WORKER_NOW=' . escapeshellarg(site_clock('06:45')) . ' php -r ' . escapeshellarg('require "' . dirname(__DIR__, 3) . '/app/bootstrap.php"; require "' . dirname(__DIR__, 3) . '/app/features/projection/worker.php"; echo json_encode(projection_pass_suggested(db(), 200, new DateTimeImmutable(getenv("RI_WORKER_NOW")), false));') . ' 2>/dev/null');
ok(str_contains((string) $out, '"drafted":0'), 'the quarter-hour gate lets :45 through and finds nothing to do');
ok((int) one("SELECT count(*) FROM purchase_order_lines l JOIN purchase_orders p ON p.id = l.purchase_order_id WHERE p.origin = 'agent' AND l.need_base IS NOT NULL AND l.have_base IS NOT NULL AND l.raw_base IS NOT NULL AND l.rounding_note IS NOT NULL") === (int) one("SELECT count(*) FROM purchase_order_lines l JOIN purchase_orders p ON p.id = l.purchase_order_id WHERE p.origin = 'agent'"), 'every drafted line carries its arithmetic');
ok(page($marco, '/projection/proposals?date=' . day(0))['code'] === 200 && has(page($marco, '/projection/proposals?date=' . day(0)), 'proposal-group-stockouts'), 'the proposals screen shows the worker\'s findings under the headings');

echo "3. watches and the rest\n";
$rep = worker('watches');
ok($rep['errors'] === [] && array_key_exists('fired', $rep['ran']['watches']), 'the watches pass answers a count');
$stubs = worker('notify_outbox,dispatches,morning_note_inputs');
ok($stubs['errors'] === [] && ($stubs['ran']['dispatches']['stub'] ?? '') === 'slice 9', 'slice 9\'s passes are untouched stubs');
$all = worker('key_usage_prune');
ok($all['errors'] === [], 'the kit\'s pass still runs');
$bad = shell_exec('php ' . escapeshellarg(dirname(__DIR__, 3) . '/bin/worker.php') . ' --passes=nonsense 2>&1');
ok(str_contains((string) $bad, 'Unknown pass'), 'an unknown pass is refused by name');
finish();
